def infer_topic_from_reply(reply, current_topic=None):
    """
    Déduit le thème de la DERNIÈRE question posée par M. Dujardin.

    La V3.9 pouvait parfois conserver le thème précédent lorsqu'une transition
    disait par exemple « Maintenant, parlons de la douleur » après une phrase
    contenant encore « gonflement ». Cette version privilégie les formulations
    de question et, en dernier recours, le mot-clé situé le plus tard dans le message.
    """
    lower = (reply or "").lower()

    # --- Phagocytose : états fins, testés avant les mots-clés généraux. ---
    if (
        ("comment s'appellent" in lower and "étape" in lower)
        or ("dans quel ordre" in lower and "étape" in lower)
        or ("quelles étapes" in lower and "ordre" in lower)
    ):
        return "PHAGO_ETAPES"

    if (
        "combien" in lower
        and "étape" in lower
        and ("mécanisme" in lower or "phagocyt" in lower)
    ):
        return "PHAGO_NOMBRE"

    if (
        (
            "comment appelle" in lower
            or "comment s'appelle" in lower
            or "quel est le nom" in lower
        )
        and "mécanisme" in lower
        and ("microbe" in lower or "leucocyte" in lower or "phagocyt" in lower)
    ):
        return "PHAGO_NOM"

    if (
        ("explique" in lower or "expliquer" in lower)
        and "étape" in lower
        and ("phagocyt" in lower or "mécanisme" in lower)
    ):
        return "PHAGO_EXPLICATION"

    # --- Début de la consultation. ---
    if "qu'est-ce qui arrive à ma main" in lower:
        return "IDENTIFICATION"

    if "quatre signes" in lower or "4 signes" in lower:
        return "SIGNES"

    # --- Chercher le thème mentionné le plus tard dans le message. ---
    # Ceci sécurise les transitions du type :
    # « ... gonflement. Maintenant, parlons de la douleur. Pourquoi ... ? »
    topic_keywords = {
        "ROUGEUR": ["rougeur", "rouge"],
        "CHALEUR": ["chaleur", "chaude", "plus chaude"],
        "GONFLEMENT": ["gonflement", "gonflée", "gonflé"],
        "DOULEUR": ["douleur", "douloureuse", "mal"],
        "SENTINELLES": ["cellules sentinelles", "cellule sentinelle"],
        "LEUCOCYTES": ["leucocytes", "leucocyte", "globules blancs", "globule blanc", "cellules de défense"],
    }

    best_topic = None
    best_position = -1

    for topic, keywords in topic_keywords.items():
        for keyword in keywords:
            pos = lower.rfind(keyword)
            if pos > best_position:
                best_position = pos
                best_topic = topic

    if best_topic is not None:
        return best_topic

    return current_topic

def strip_support_markers(reply):
    reply = reply or ""

    topic_match = re.search(r"\[\[TOPIC:([A-Z_]+)\]\]", reply)
    document_match = re.search(r"\[\[DOCUMENT:([A-Z0-9_]+)\]\]", reply)
    activity_match = re.search(r"\[\[ACTIVITY:([A-Z0-9_]+)\]\]", reply)
    video_match = re.search(r"\[\[VIDEO:([A-Z0-9_]+)\]\]", reply)

    cleaned = re.sub(
        r"\s*\[\[(?:TOPIC|DOCUMENT|ACTIVITY|VIDEO):[A-Z0-9_]+\]\]\s*",
        " ",
        reply,
    ).strip()

    return (
        cleaned,
        topic_match.group(1) if topic_match else None,
        document_match.group(1) if document_match else None,
        activity_match.group(1) if activity_match else None,
        video_match.group(1) if video_match else None,
    )






